import { useEffect, useMemo, useState } from 'react';

const API = import.meta.env.VITE_API_BASE_URL || 'http://localhost:3000/api';

async function api(path, options = {}) {
  const token = sessionStorage.getItem('accessToken');
  const response = await fetch(`${API}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...(options.headers || {})
    }
  });

  const body = await response.json().catch(() => null);
  if (!response.ok) throw new Error(body?.error || 'Request failed');
  return body;
}

export default function App() {
  const [authMode, setAuthMode] = useState('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [auth, setAuth] = useState(null);
  const [tasks, setTasks] = useState([]);
  const [status, setStatus] = useState('all');
  const [priorityFilter, setPriorityFilter] = useState('all');
  const [title, setTitle] = useState('');
  const [priority, setPriority] = useState('medium');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const visibleTasks = useMemo(() => tasks.filter(task => {
    const statusMatch = status === 'all' || task.status === status;
    const priorityMatch = priorityFilter === 'all' || task.priority === priorityFilter;
    return statusMatch && priorityMatch;
  }), [tasks, status, priorityFilter]);

  async function loadTasks() {
    const result = await api('/tasks?limit=50');
    setTasks(result.items);
  }

  useEffect(() => {
    if (!sessionStorage.getItem('accessToken')) return;
    Promise.all([api('/auth/me'), loadTasks()])
      .then(([profile]) => setAuth(profile))
      .catch(() => { sessionStorage.removeItem('accessToken'); setAuth(null); });
  }, []);

  async function submitAuth(event) {
    event.preventDefault();
    setError('');
    setLoading(true);
    try {
      const path = authMode === 'login' ? '/auth/login' : '/auth/register';
      const result = await api(path, { method: 'POST', body: JSON.stringify({ email, password }) });
      sessionStorage.setItem('accessToken', result.accessToken);
      setAuth(result.user);
      setEmail('');
      setPassword('');
      await loadTasks();
    } catch (err) { setError(err.message); }
    finally { setLoading(false); }
  }

  async function createTask(event) {
    event.preventDefault();
    setError('');
    try {
      const created = await api('/tasks', {
        method: 'POST',
        body: JSON.stringify({ title, priority })
      });
      setTasks(current => [created, ...current]);
      setTitle('');
    } catch (err) { setError(err.message); }
  }

  async function toggleTask(task) {
    setError('');
    try {
      const updated = await api(`/tasks/${task._id}`, {
        method: 'PATCH',
        body: JSON.stringify({ status: task.status === 'done' ? 'open' : 'done' })
      });
      setTasks(current => current.map(item => item._id === updated._id ? updated : item));
    } catch (err) { setError(err.message); }
  }

  function logout() {
    sessionStorage.removeItem('accessToken');
    setAuth(null);
    setTasks([]);
  }

  if (!auth) {
    return (
      <main className="container narrow">
        <h1>Team Task Board</h1>
        <p>{authMode === 'login' ? 'Sign in to continue.' : 'Create a member account.'}</p>
        <form onSubmit={submitAuth} className="stack">
          <label htmlFor="email">Email</label>
          <input id="email" type="email" autoComplete="email" value={email} onChange={e => setEmail(e.target.value)} required />
          <label htmlFor="password">Password</label>
          <input id="password" type="password" autoComplete={authMode === 'login' ? 'current-password' : 'new-password'} minLength={8} value={password} onChange={e => setPassword(e.target.value)} required />
          <button type="submit" disabled={loading}>{loading ? 'Working…' : authMode === 'login' ? 'Sign in' : 'Register'}</button>
        </form>
        {error && <p role="alert">{error}</p>}
        <button type="button" className="link-button" onClick={() => { setError(''); setAuthMode(mode => mode === 'login' ? 'register' : 'login'); }}>
          {authMode === 'login' ? 'Create an account' : 'Back to sign in'}
        </button>
      </main>
    );
  }

  return (
    <main className="container">
      <header className="toolbar">
        <div><h1>Team Task Board</h1><p>Signed in as <strong>{auth.email}</strong> ({auth.role})</p></div>
        <button type="button" onClick={logout}>Sign out</button>
      </header>
      {error && <p role="alert">{error}</p>}

      <section className="card" aria-labelledby="create-heading">
        <h2 id="create-heading">Create task</h2>
        <form onSubmit={createTask} className="grid-form">
          <label htmlFor="task-title">Title</label>
          <input id="task-title" value={title} onChange={e => setTitle(e.target.value)} minLength={3} maxLength={120} required />
          <label htmlFor="task-priority">Priority</label>
          <select id="task-priority" value={priority} onChange={e => setPriority(e.target.value)}>
            <option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option>
          </select>
          <button type="submit">Add task</button>
        </form>
      </section>

      <section className="card" aria-labelledby="filters-heading">
        <h2 id="filters-heading">Filters</h2>
        <div className="filters">
          <label htmlFor="status-filter">Status</label>
          <select id="status-filter" value={status} onChange={e => setStatus(e.target.value)}>
            <option value="all">All</option><option value="open">Open</option><option value="done">Done</option>
          </select>
          <label htmlFor="priority-filter">Priority</label>
          <select id="priority-filter" value={priorityFilter} onChange={e => setPriorityFilter(e.target.value)}>
            <option value="all">All</option><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option>
          </select>
        </div>
      </section>

      <section className="card" aria-labelledby="tasks-heading">
        <h2 id="tasks-heading">Tasks</h2>
        {visibleTasks.length === 0 ? <p>No tasks match the selected filters.</p> : (
          <ul className="task-list" aria-live="polite">
            {visibleTasks.map(task => <li key={task._id}><div><strong>{task.title}</strong><span className="meta">{task.status} · {task.priority}</span></div><button type="button" onClick={() => toggleTask(task)}>{task.status === 'done' ? 'Reopen' : 'Complete'}</button></li>)}
          </ul>
        )}
      </section>
    </main>
  );
}

