import mongoose from 'mongoose';

const userSchema = new mongoose.Schema({
  email: { type: String, required: true, unique: true, trim: true, lowercase: true, maxlength: 254 },
  passwordHash: { type: String, required: true, select: false },
  role: { type: String, enum: ['member', 'admin'], default: 'member' }
}, { timestamps: true });

const taskSchema = new mongoose.Schema({
  ownerId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
  title: { type: String, required: true, trim: true, minlength: 3, maxlength: 120 },
  description: { type: String, default: '', trim: true, maxlength: 5000 },
  status: { type: String, enum: ['open', 'done'], default: 'open' },
  priority: { type: String, enum: ['low', 'medium', 'high'], default: 'medium' }
}, { timestamps: true });

taskSchema.index({ ownerId: 1, status: 1, createdAt: -1 });
taskSchema.index({ ownerId: 1, priority: 1, createdAt: -1 });

export const User = mongoose.model('User', userSchema);
export const Task = mongoose.model('Task', taskSchema);

import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { config } from './config.js';

export const hashPassword = password => bcrypt.hash(password, 12);
export const verifyPassword = (password, hash) => bcrypt.compare(password, hash);

export function issueAccessToken(user) {
  if (!config.jwtSecret) throw new Error('JWT_SECRET is required');
  return jwt.sign({ sub: user._id.toString(), role: user.role }, config.jwtSecret, { expiresIn: '15m' });
}

export function authRequired(req, res, next) {
  const [scheme, token] = (req.get('Authorization') || '').split(' ');
  if (scheme !== 'Bearer' || !token || !config.jwtSecret) return res.status(401).json({ error: 'Authentication required' });
  try { req.auth = jwt.verify(token, config.jwtSecret); next(); }
  catch { return res.status(401).json({ error: 'Authentication required' }); }
}

export function adminRequired(req, res, next) {
  if (req.auth?.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  next();
}

import { Router } from 'express';
import { Task, User } from './models.js';
import { adminRequired, authRequired } from './auth.js';

const router = Router();
const statuses = new Set(['open', 'done']);
const priorities = new Set(['low', 'medium', 'high']);
const sortMap = { newest: { createdAt: -1 }, priority: { priority: -1, createdAt: -1 } };

router.get('/', authRequired, async (req, res, next) => {
  try {
    const page = Math.max(parseInt(req.query.page || '1', 10), 1);
    const limit = Math.min(Math.max(parseInt(req.query.limit || '20', 10), 1), 100);
    const filter = req.auth.role === 'admin' ? {} : { ownerId: req.auth.sub };

    if (req.query.status !== undefined) {
      if (!statuses.has(req.query.status)) return res.status(400).json({ error: 'Unsupported status' });
      filter.status = req.query.status;
    }
    if (req.query.priority !== undefined) {
      if (!priorities.has(req.query.priority)) return res.status(400).json({ error: 'Unsupported priority' });
      filter.priority = req.query.priority;
    }

    const [items, total] = await Promise.all([
      Task.find(filter).sort(sortMap[req.query.sort] || sortMap.newest).skip((page - 1) * limit).limit(limit).select('ownerId title description status priority createdAt updatedAt'),
      Task.countDocuments(filter)
    ]);
    res.json({ items, page, limit, total });
  } catch (err) { next(err); }
});

router.post('/', authRequired, async (req, res, next) => {
  try {
    const { title, description = '', priority = 'medium' } = req.body ?? {};
    if (typeof title !== 'string' || title.trim().length < 3) return res.status(400).json({ error: 'title must contain at least 3 characters' });
    if (!priorities.has(priority)) return res.status(400).json({ error: 'Unsupported priority' });
    const task = await Task.create({ ownerId: req.auth.sub, title: title.trim(), description: typeof description === 'string' ? description.trim() : '', priority });
    res.status(201).json(task);
  } catch (err) { next(err); }
});

router.patch('/:id', authRequired, async (req, res, next) => {
  try {
    const task = await Task.findById(req.params.id);
    if (!task) return res.status(404).json({ error: 'Task not found' });
    const owner = task.ownerId.toString() === req.auth.sub;
    const admin = req.auth.role === 'admin';
    if (!owner && !admin) return res.status(403).json({ error: 'Forbidden' });

    const { title, description, status, priority } = req.body ?? {};
    if (title !== undefined) {
      if (typeof title !== 'string' || title.trim().length < 3) return res.status(400).json({ error: 'title must contain at least 3 characters' });
      task.title = title.trim();
    }
    if (description !== undefined) {
      if (typeof description !== 'string') return res.status(400).json({ error: 'description must be a string' });
      task.description = description.trim();
    }
    if (status !== undefined) {
      if (!statuses.has(status)) return res.status(400).json({ error: 'Unsupported status' });
      task.status = status;
    }
    if (priority !== undefined) {
      if (!priorities.has(priority)) return res.status(400).json({ error: 'Unsupported priority' });
      task.priority = priority;
    }
    await task.save();
    res.json(task);
  } catch (err) { next(err); }
});

router.delete('/:id', authRequired, async (req, res, next) => {
  try {
    const task = await Task.findById(req.params.id);
    if (!task) return res.status(404).json({ error: 'Task not found' });
    const owner = task.ownerId.toString() === req.auth.sub;
    if (!owner && req.auth.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
    await task.deleteOne();
    res.status(204).end();
  } catch (err) { next(err); }
});

