app.post('/api/auth/register', async (req, res, next) => {
  try {
    const email = typeof req.body?.email === 'string' ? req.body.email.trim().toLowerCase() : '';
    const password = req.body?.password;
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return res.status(400).json({ error: 'Valid email is required' });
    if (typeof password !== 'string' || password.length < 8) return res.status(400).json({ error: 'Password must be at least 8 characters' });
    if (await User.exists({ email })) return res.status(409).json({ error: 'Account already exists' });
    const user = await User.create({ email, passwordHash: await hashPassword(password), role: 'member' });
    res.status(201).json({ accessToken: issueAccessToken(user), user: { _id: user._id, email: user.email, role: user.role } });
  } catch (err) { next(err); }
});

app.post('/api/auth/login', async (req, res, next) => {
  try {
    const email = typeof req.body?.email === 'string' ? req.body.email.trim().toLowerCase() : '';
    const password = req.body?.password;
    const user = await User.findOne({ email }).select('+passwordHash');
    if (!user || typeof password !== 'string' || !(await verifyPassword(password, user.passwordHash))) return res.status(401).json({ error: 'Invalid credentials' });
    res.json({ accessToken: issueAccessToken(user), user: { _id: user._id, email: user.email, role: user.role } });
  } catch (err) { next(err); }
});

app.get('/api/auth/me', authRequired, async (req, res, next) => {
  try {
    const user = await User.findById(req.auth.sub).select('_id email role createdAt');
    if (!user) return res.status(401).json({ error: 'Authentication required' });
    res.json(user);
  } catch (err) { next(err); }
});

